import urllib.request, re, html
feeds={
'CryptoBriefing':'https://cryptobriefing.com/feed/',
'Cointelegraph':'https://cointelegraph.com/rss',
'BeInCrypto':'https://beincrypto.com/feed/'
}
for name,u in feeds.items():
  try:
    data=urllib.request.urlopen(urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0 (compatible; OpenClawScout/1.0)'}),timeout=20).read().decode('utf-8','ignore')
  except Exception as e:
    print(name,'ERR',e)
    continue
  print('##',name)
  for pat in ['Iran','cryptocurrency','Operation Economic Fury','7.7B','500M']:
    if pat.lower() in data.lower():
      print('contains',pat)
  for m in re.finditer(r'<item>\s*<title>(.*?)</title>\s*<link>(.*?)</link>.*?<pubDate>(.*?)</pubDate>.*?<description>(.*?)</description>.*?</item>', data, re.S):
    t=html.unescape(re.sub('<.*?>','',m.group(1)).strip())
    if any(k in t.lower() for k in ['iran','crypto','bitcoin']):
      print('TITLE:',t)
      print('LINK:',html.unescape(re.sub('<.*?>','',m.group(2)).strip()))
      print('PUB:',html.unescape(re.sub('<.*?>','',m.group(3)).strip()))
      print('DESC:',html.unescape(re.sub('<.*?>','',m.group(4)).strip())[:300])
